<?php
namespace App\Http\Controllers;use App\Models\{GeneratedReport,Project,Employee};use App\Services\ReportGenerationService;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;class ReportController extends Controller{function index(){return view('reports.index',['items'=>GeneratedReport::latest()->paginate(20),'projects'=>Project::all(),'employees'=>Employee::all()]);}function generate(Request $r,ReportGenerationService $s){$d=$r->validate(['report_type'=>'required','file_type'=>'required','project_id'=>'nullable','employee_id'=>'nullable','month'=>'nullable','year'=>'nullable']);$s->generate($d['report_type'],$d['file_type'],$d,auth()->id());return back()->with('success','Report generated');}function generateAll(Request $r,ReportGenerationService $s){$s->generateAll($r->all(),auth()->id());return back()->with('success','All reports ZIP generated');}function download(GeneratedReport $generatedReport){return Storage::download($generatedReport->file_path);}}
